const items = $input.all();
const results = [];

for (const item of items) {
  const data = item.json;
  const isPack = data.type === 'pack';

  const name = data.name || 'Complément Alimentaire';
  const category = data.category || 'Supplements';

  let prompt = '';
  if (isPack) {
    const itemsList = (data.items && Array.isArray(data.items))
      ? data.items.map(i => i.name).filter(Boolean).join(', ')
      : name;
    prompt = `Commercial 3D e-commerce studio photography of a fitness supplement bundle pack: ${itemsList || name}. Premium matte black and neon lime supplement tubs and jars, sleek shaker bottle, displayed on a clean dark reflective carbon surface, soft gym background bokeh, dynamic neon edge lighting, ultra-realistic, 8k resolution, crisp photorealistic mockup`;
  } else {
    prompt = `Commercial 3D e-commerce studio product photography of ${name}, category ${category}. Premium fitness supplement tub on clean dark reflective gym surface, neon green and purple rim lighting, ultra-sharp focus, photorealistic packaging, 8k resolution, advertising quality`;
  }

  const encodedPrompt = encodeURIComponent(prompt.trim());
  const hash = Math.abs(name.split('').reduce((acc, char) => (acc << 5) - acc + char.charCodeAt(0), 0)) % 1000000;

  // Free high-speed AI image generator using Flux
  const aiImageUrl = `https://image.pollinations.ai/prompt/${encodedPrompt}?width=1024&height=1024&model=flux&seed=${hash}&nologo=true`;

  // AI visual is primary image, original IG story image is secondary fallback
  const images = [aiImageUrl];
  if (data.imageUrl && data.imageUrl.startsWith('http')) {
    images.push(data.imageUrl);
  }

  results.push({
    json: {
      ...data,
      aiImageUrl,
      generatedPrompt: prompt,
      images
    }
  });
}

return results;

const pack = $json;
const name = pack.name || 'Pack Spécial Ghaith Nutrition';
const price = pack.price ? `${pack.price} DT` : '';
const originalPrice = pack.originalPrice ? `${pack.originalPrice} DT` : '';
const discount = (pack.originalPrice && pack.price && pack.originalPrice > pack.price)
  ? ` (Économisez ${Math.round(pack.originalPrice - pack.price)} DT !)`
  : '';
const tagline = pack.tagline ? `\n⚡ ${pack.tagline}` : '';
const shopUrl = `https://gympilot.tn/shop/pack/${pack.slug || pack.id}`;
const imageUrl = (pack.images && pack.images.length > 0) ? pack.images[0] : '';

const caption = `🔥 NOUVEAU PACK DISPONIBLE SUR GYMPILOT ! 🔥\n\n` +
  `💪 ${name}\n` +
  `${tagline}\n\n` +
  `💰 Prix Promo : ${price}${discount}\n` +
  `🚚 Livraison Express 24-48h partout en Tunisie\n` +
  `💵 Paiement à la livraison (Cash on Delivery)\n` +
  `✨ Produits 100% Certifiés & Authentiques\n\n` +
  `👉 Commandez directement en 1 clic : ${shopUrl}\n` +
  `(Lien direct disponible aussi en Bio !)\n\n` +
  `#GymPilot #GhaithNutrition #MusculationTunisie #WheyProtein #Creatine #MassGainer #FitnessTunisie #BodybuildingTunisia #SupplementsTunisie`;

return [{
  json: {
    packId: pack.id,
    packName: name,
    imageUrl: imageUrl,
    caption: caption,
    shopUrl: shopUrl,
    price: price
  }
}];

const igRes = $json;
const postData = $('📝 Format Instagram Post').first().json;

return [{
  json: {
    success: true,
    instagramPostId: igRes.id || 'simulated_or_pending',
    packName: postData.packName,
    shopUrl: postData.shopUrl,
    imageUrl: postData.imageUrl,
    publishedAt: new Date().toISOString(),
    message: `Successfully published ${postData.packName} to Instagram feed!`
  }
}];
